import json,re
from pathlib import Path
files={}
for row in json.loads(Path("analysis/initial.json").read_text())["findings"]:
 for file,line,fragment in re.findall(r'(gobreaker\.go|analysis/_probe/identity_test\.go):(\d+) \("([^"\n]*(?:\\"[^"\n]*)*)"\)',row["outcome"]):
  if file not in files:
   files[file]=Path(file).read_text().splitlines()
  actual=files[file][int(line)-1]
  if fragment.replace(r'\"','"') not in actual:
   print(row["id"],file,line,repr(fragment),repr(actual))
print("checked",list(files))
